/// Returns the compiled token grammar for a resolved
/// [supportedPythonVersions] entry. Callers must resolve
/// through [resolvePythonVersion] first.
TokenGrammar tokenGrammarForLegacyVersion(String version) =>
    _legacyByVersion[version]!;

/// The TokenGrammar of exactly [release], or `null`. There
/// is no default and no fallback: unknown IDs, pending
/// rows, and legacy minor lines all answer `null` (LANG84
/// C4 — the two tables never mix).
TokenGrammar? tokenGrammarForRelease(String release) => _releaseById[release];

/// The grammar class of exactly [release], or `null` for
/// anything without a table. Releases whose token files are
/// identical share one class.
String? pythonGrammarClass(String release) => _classByRelease[release];
